// AUTO-GÉNÉRÉ — actifs embarqués (base64) pour la génération des PDF du club.
// Source : `.data/modèles/courrier/` (papier à lettre) et le modèle Word d'origine
// (tampon, signature). Empaquetés dans le worker API, qui n'a pas de système de fichiers.
// Ne pas éditer à la main ; régénérer via `scripts/build-letterhead-assets.py`.

export type EmbeddedImage = { base64: string; kind: 'jpg' | 'png' };

const img = (base64: string, kind: 'jpg' | 'png'): EmbeddedImage => ({ base64, kind });

/** Bande d'en-tête pleine largeur (dégradé + écusson du club). */
export const letterheadHeader = img(
  '',
  'jpg'
);

/** Bas de page « Merci pour leur soutien » + www.nozaybad.fr. */
export const letterheadFooter = img(
  '',
  'png'
);

/** Logo partenaire : ville de Nozay. */
export const logoVilleNozay = img(
  '',
  'png'
);

/** Logo partenaire : Lardé Sports. */
export const logoLardeSports = img(
  '',
  'png'
);

/** Tampon du club (modèle Word d'origine). */
export const stamp = img(
  '',
  'jpg'
);

/** Signature de repli, quand aucune n'est configurée. */
export const defaultSignature = img(
  '',
  'jpg'
);
